fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // For three points, the sum of absolute distances to a meeting point
    // is minimized when the meeting point is the median of the three.
    let mut xs = [x1, x2, x3];
    xs.sort();
    let median = xs[1];
    (xs[0] - median).abs() + (xs[1] - median).abs() + (xs[2] - median).abs()
}

